-- 2027 资料核对第十八批（专门学校 4 所）。
-- NOT EXECUTED：截至 2026-11-18，Supabase MCP 与本机 REST 通道均不可达；待连接恢复后应用。
-- 保留为等价的可审计 SQL 工件；下方校验在任一 slug 缺失时中止。
-- 来源与限制见 docs/REDESIGN-AND-DATA.md 与 data/school-reviews.ts。
-- 受控同步：仅 4 条 VocationalSchool 记录按 slug upsert；无 DELETE、无批量导入、无表结构变更。
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "VocationalSchool" WHERE slug IN ('jec', 'nihonkogakuin', 'kobe-denshi', 'bunka-fashion')) <> 4 THEN
    RAISE EXCEPTION '本批目标学校记录缺失，已中止，未应用任何更新';
  END IF;
END $$;
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "website", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES (
  'jec', '日本电子专门学校', '日本電子専門学校', 'IT / 电子 / 动漫', '东京（新宿）', '留学生2027年度官方口径：按学科列到毕业为止的缴纳总额（不含教科书与教材费），2年制2,318,200～2,659,800日元、3年制3,764,000～3,903,200日元、4年制（高度游戏制作科）5,146,600日元；选考料20,000日元、入学金200,000日元。首年度分项学费表为PDF图形，本批未能读取，分项金额待校方要项确认。', '2年制学科到毕业为止合计（留学生2027年度，不含教科书与教材）：CG・动画・游戏制作等2,659,800日元；AI・Web・情报处理等2,491,000日元；电气工学・电子应用工学2,318,200日元；电气工事技术2,333,000日元', '1951年创立的东京新宿IT与动漫系专门学校；2027年度留学生为书类审查＋日语笔试＋面试，JLPT N2／EJU日语200分以上／BJT 400分以上可免笔试；2027年度留学生合计费用按学科为2,318,200～5,146,600日元。', '未核实（官网留学生页未公开就业率数字）', '官网未见可核对的就业率统计；旧的“IT系就職率ほぼ100%”“2023年度内定率98.5%”等数字无官方来源，已删除。', '合格后7日内缴纳入学手续金（入学金＋前期学费）；具体分期与缴纳期限按校方要项，本批未取得可读文本，待确认。', '2年制、3年制毕业授予「专门士」称号（官网QA明记）；4年制的授予称号官网未明文，待确认。官网另载一定条件下可获专门士或高度专门士称号并编入大学。', '2027年度留学生出愿资格：前籍校出席率80%以上（出席时间数）。', 'https://www.jec.ac.jp/entrance/foreign_guideline/', '["1951年创立（学校法人电子学园），东京新宿百人町","昼间部与夜间部合计25个学科（CG、游戏、动画、设计、AI、Web、情报处理、网络安全、电气电子）","官网自述2014年度起昼间部全学科获职业实践专门课程认定","仅4月入学（官网FAQ明确：本校は4月入学のみ）","2年制、3年制毕业获专门士称号（官网QA明记）"]'::jsonb, '[{"name":"アニメーション科（2年）／アニメーション研究科（3年）","description":"动画制作方向；2027年度留学生到毕业合计2,659,800日元（研究科3,903,200日元）。","duration":"2年／3年","totalCost":"2年制2,659,800日元／3年制3,903,200日元（不含教科书教材）"},{"name":"ゲーム制作科（2年）／ゲーム制作研究科（3年）／高度ゲーム制作科（4年）","description":"游戏制作方向；高度ゲーム制作科为4年制。","duration":"2年／3年／4年","totalCost":"2年制2,659,800日元／3年制3,883,200日元／4年制5,146,600日元"},{"name":"AIシステム科（2年）","description":"AI方向，公开EJU科目制与专门士认定；按学科合计2,491,000日元。","duration":"2年","totalCost":"2,491,000日元（不含教科书教材）"},{"name":"情報処理関連（情報処理科・情報システム開発科・DXスペシャリスト科・高度情報処理科等）","description":"情报处理系学科；高度情報処理科为3年制。","duration":"2年／3年","totalCost":"2年制2,491,000日元／3年制3,764,000日元"},{"name":"ネットワークセキュリティ科（2年）","description":"网络与安全方向；另设夜间部同名学科。","duration":"2年","totalCost":"2,491,000日元"},{"name":"電気工学科・電子応用工学科・電気工事技術科","description":"电气电子方向，2年制。","duration":"2年","totalCost":"2,318,200日元／2,333,000日元"}]'::jsonb, '{"enrollmentFee":"入学金200,000日元（留学生2027年度）","admissionFee":"选考料20,000日元；参加开放校园或特别讲习并于2026-12-22前出愿可免除","annualTuition":"官网留学生页仅列到毕业为止的合计，未逐项公开年间授课费；分项见校方学费PDF，本批未能读取，待确认。","facilitiesFee":"待校方要项确认（未从上表分项中拆出）","practiceMaterialsFee":"教材费不在官方合计内，需另计","totalFirstYear":"待校方要项确认；合格后7日内须缴纳入学手续金（入学金＋前期学费）"}'::jsonb, '["IT/软件开发","网络安全方向","动漫/CG制作","希望在东京新宿就读"]'::jsonb, '["特别奨学生（留学生对象，2名）：N1总分135分以上或EJU总分340分以上、出席率95%以上，缴纳金减免40万日元（不含入学金与授课费），申请2026-09-01至11-06","文部科学省外国人留学生学习奖励费（JASSO）：推荐制，月额48,000日元，入学后满1年且出席率良好等条件","共立国际交流奖学财团月额100,000日元（1年）、共立维护奖学基金月额60,000日元（1年）、新宿区年额240,000日元","上述外部奖学金与本校特别奨学生制度不可重复适用（官网明记）"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "website", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES (
  'nihonkogakuin', '日本工学院', '日本工学院', '动漫 / IT / 设计 / 音乐', '东京（蒲田/八王子）', '官网学费页：入学金一律200,000日元（针灸科、柔道整复科300,000日元），授课费含设施设备费；首年缴纳额2年制多为1,466,010日元，AI系统科与情报处理科1,341,010日元，电子电气科1,316,010日元，3年制1,467,940日元，4年制1,469,770日元。该页未标注年度（仅教材费注明按2026年度概算），亦未写明留学生与日本学生同额，2027年度留学生适用金额待校方要项确认。', '官网按年度列示，未公开到毕业为止的合计；2年制首年约131.6万～150.6万日元，第二年金额按学科另行公布，待确认', '片柳学园旗下东京蒲田与八王子两校区综合专门学校，官网列36学科；2027年度留学生选考为书类审查＋面试＋JLPT N2相当日语笔试，日语达N2／EJU日语200分以上／BJT 400分以上等条件者可出愿。', '未核实（官网未公开就业率数字）', '官网仅列留学生就职企业例（CAPCOM、Cygames、KONAMI、SUBARU、JR东日本等）及“对在日本就业提供全面支援”的表述，未给出可核对的就业率，旧的就业率数字已删除。', '按校方入学手续期限缴纳首年费用；分期与具体期限按招募要项，本批未从官网取得，待确认。', '官网明记毕业称号为「专门士」或「高度专门士」；获得职业实践专门课程认定。各学科具体授予哪一称号待按要项确认。', '2027年度留学生出愿资格：出席率（时数出席率）80%以上。', 'https://www.neec.ac.jp/portal/admission/abroad/', '["1947年创美学园创立，1976年设日本工学院专门学校；设置者为学校法人片柳学园","官网自述创校79年、毕业生约26.4万人（含北海道校）","全站列36学科，分为创作者与表演、专业职员、技术专家三类","蒲田校、八王子校、北海道校、名古屋校","官网写明毕业称号为专门士或高度专门士"]'::jsonb, '[{"name":"漫画家・动画类（マンガ・アニメーション科、グローバルアニメクリエイター科等）","description":"动画与漫画方向，グローバルアニメクリエイター科仅在蒲田校开设，为4年制。","duration":"2年／4年","totalCost":"2年制首年1,466,010日元／4年制首年1,469,770日元"},{"name":"ゲームクリエイター科・CG映像科・デザイン科等","description":"游戏创作、CG影像与设计方向，设3年制与4年制。","duration":"2年／3年／4年","totalCost":"3年制首年1,467,940日元／4年制首年1,469,770日元"},{"name":"AIシステム科・サイバーセキュリティ科（ITスペシャリスト科等）","description":"IT与网络安全方向；ITスペシャリスト科与网络安全科为4年制。","duration":"2年／4年","totalCost":"2年制首年1,341,010日元／4年制首年1,344,770日元"},{"name":"声優・演劇科、音響・ミュージック系","description":"声优、舞台与音乐方向，蒲田校另设演剧职员科。","duration":"2年","totalCost":"声优・演剧首年1,466,010日元／音响音乐类1,506,010日元"},{"name":"八王子校专门学科（鍼灸科、柔道整復科、自動車整備科、建築学科等）","description":"医疗保健、汽车整备、建筑、运动健康等方向，仅八王子校开设。","duration":"2年／3年／4年","totalCost":"各学科金额按官网学费页；针灸与柔道整复入学金300,000日元"}]'::jsonb, '{"enrollmentFee":"入学金200,000日元（针灸科、柔道整复科300,000日元）","admissionFee":"选考料按2027年度招募要项PDF，本批未取得金额，待确认","annualTuition":"官网不单列授课费：授课费包含设施设备费；各学科“其他诸费”单列学生灾害伤害保险费、校内志费、校友会费等","facilitiesFee":"包含在授课费内（官网原文：授業料には施設設備費が含まれています）","practiceMaterialsFee":"教材费另计，官网注明金额为按2026年度概算","totalFirstYear":"2年制多为1,466,010日元；音响/演唱会/音乐/舞蹈1,506,010日元；AI系统科/情报处理科1,341,010日元；电子电气科/机械设计科1,316,010日元；建筑设计科1,336,010日元；3年制1,467,940日元；4年制1,469,770日元"}'::jsonb, '["动漫/游戏/影像方向","IT/网络安全方向","希望东京圈就读","需要校内宿舍"]'::jsonb, '["留学生特别给付制度：给付10万、20万或30万日元，按笔试结果评审，可与片柳学园入学金免除制度并用（免除20万日元）","学生寮奖学金制度（2027年度留学生）：按房费减免月额26,000日元（全年312,000日元），定员5名，第1期笔试与面试选拔，出席不良或留级取消","JASSO奖学金：官网仅介绍第一种（无息）与第二种（有息）制度，未列金额"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "website", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES (
  'kobe-denshi', '神户电子专门学校', '神戸電子専門学校', 'IT / 动漫 / 设计', '兵库（神户）', '2027年度留学生募集要项：入学金200,000日元（仅初年度），授课费前期与后期各按学科计，设施实习诸费为年额；AI系统开发/IT专业/情报处理/游戏制作等首年1,340,000日元，情报工（机器人控制）1,320,000日元，情报商务1,280,000日元，eスポーツ工程师/音响类1,460,000日元，声优艺人1,390,000日元。另需修养费、教科书及笔记本电脑（2027年度金额预计2027年2月中旬通知）。', '第二年无入学金：AI/IT/情报处理/游戏制作/3DCG动画/2D动画1,190,000日元，情报工与建筑设计1,170,000，情报商务1,080,000，eスポーツ/音响/声优1,310,000日元；2年制合计约236万～277万日元（不含教科书与电脑）', '神户IT与创意系总合专门学校，2027年度外国人募要项明确私费留学生与日本学生同额；选考为书类审查＋面试＋日语笔试（含作文），考试自2026年9月至2027年2月共14回，仅4月入学。', '未核实（官网未公开就业率数字）', '官网未见可核对的就业率统计；旧“关西圈IT系就職率约96%”无官方来源，已删除。官网就职支援页载校内企业说明会等支援内容，具体数字待确认。', '入学手续在合格后约4周内完成；后期授课费支付期限预计2027-09-30（2027年度要项）。', '2年制毕业授予专门士、4年制授予高度专门士（本批未取得官网授予条件的原文条款，具体按学则确认）。', '2027年度留学生出愿资格：各年级出席率90%以上；推荐种别需96%以上、自我推荐种别93%以上。', 'https://ryugaku.kobedenshi.ac.jp/admission/', '["1958年创立，设置者为学校法人计算机综合学园；1976年成为兵库县首个工业系专修学校","20个学科（2年制15、3年制2、4年制2）及综合研究科、国际交流学科、日本语学科","4年制的IT专家学科与游戏工程师学科","官网明记私费留学生与日本学生同学费（2027年度留学要项）","外国人专用募集要项另设推荐、自我推荐、一般三种出愿种别"]'::jsonb, '[{"name":"ITエキスパート科（4年）","description":"4年制IT专家学科；首年1,340,000日元（含设施实习诸费100,000），第二年起1,190,000日元。","duration":"4年","totalCost":"首年1,340,000日元"},{"name":"AIシステム開発科・ITスペシャリスト科・情報処理科（2—3年）","description":"AI开发、IT专家与情报处理方向。","duration":"2年／3年","totalCost":"首年1,340,000日元"},{"name":"ゲーム開発研究科（4年）・ゲームエンジニア科（3年）・ゲーム制作科（2年）","description":"游戏开发与研究方向。","duration":"2年／3年／4年","totalCost":"首年1,340,000日元"},{"name":"3DCGアニメーション科・デジタルアニメ科","description":"3DCG与2D动画方向，均为2年制。","duration":"2年","totalCost":"3DCG首年1,340,000日元（含设施费100,000）"},{"name":"グラフィックデザイン科・インダストリアルデザイン科・建築インテリア科","description":"设计与建筑室内方向，均为2年制。图形设计与工业设计两科不实施留考（要项注记）。","duration":"2年","totalCost":"图形设计1,340,000日元／工业设计1,320,000日元"},{"name":"国際コミュニケーション学科","description":"具备N3相当日语者的学科课程；首年1,280,000日元（含设施费100,000），另有学科奖学金与出席率奖学金。","duration":"待校方要项确认","totalCost":"首年1,280,000日元"}]'::jsonb, '{"enrollmentFee":"入学金200,000日元（仅初年度）","admissionFee":"选考料按招募要项；参加校内活动可免除（官网载検定料免除20,000日元），本批未核对金额","annualTuition":"前期授课费与后期授课费同额：AI/IT/情报处理/游戏制作类各520,000日元，3DCG动画580,000日元，2D动画520,000日元，音响类535,000日元，图形设计520,000日元","facilitiesFee":"设施实习诸费为年额：AI/IT/情报处理/3DCG动画/图形设计/国际交流学科100,000日元，eスポーツ190,000日元，声优190,000日元，其余学科为0","practiceMaterialsFee":"教科书代最大约35,000日元、修养费约30,000～185,000日元、笔记本电脑84,700～256,300日元（均为2026年度实际值，2027年度待通知）","totalFirstYear":"1,280,000～1,460,000日元（含入学金；不含教科书、修养费与电脑）"}'::jsonb, '["关西圈留学","IT开発方向","CG/动画/游戏方向","希望与日本学生同等学费"]'::jsonb, '["出愿种别奖学金：推荐（专愿，出席96%以上）减免200,000日元；自我推荐（专愿，出席93%以上）减免50,000日元，JLPT N2/N1者可免笔试","私费留学生奖学金100,000日元（持“留学”在留资格入学）、资格取得特别奖学金70,000日元（N1或TOEIC 800以上或FE）","出席率优秀者奖学金100,000日元（毕业年次98%以上）、入试结果特别奖学金（面试优秀/作文优秀）各100,000日元；升级时私费留学生优秀者奖学金最大250,000日元","文部科学省外国人留学生学习奖励费（JASSO）月额48,000日元；共立国际交流奖学财团110,000日元等外部制度"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "website", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES (
  'bunka-fashion', '文化服装学院', '文化服装学院', '时尚 / 设计', '东京（新宿）', '2027年度外国人留学生募集要项「新入学各科学费他一览表」：服装科、时尚流通科、珠宝设计科、包袋设计科学费+教育充实费共，入学时缴纳990,700日元、全年1,350,700日元；3年制1,030,700／1,390,700日元；4年制高度专门士科1,070,700／1,470,700日元。另需学友会费4,500、防灾用品费6,200日元。', '2年制约2,701,400日元（服装科、时尚流通科等）；3年制约4,172,100日元；4年制约5,882,800日元（按各年次合计推算，不含学友会费与防灾用品费）', '1923年创立、2026年10月时点在册留学生930名的东京时尚专门学校；2027年度留学生分3期入试（2026-10-01起），选考为日语笔试（笔答＋400字作文）与面试，出愿须本人直接到学生课提交。', '未核实（官网未公开就业率数字）', '官网仅载就职支援内容（就职咨询、履历修改、面试练习；线上联合企业研究会60家以上、校内企业说明会每年约40家、企业研修与实习接收100家以上），未给出可核对的就业率，旧的“约96%”已删除。', '各期合格后按纳付期限一次缴清（第1期2026-12-14、第2期2027-01-18、第3期2027-02-26）；2027-03-31前完成入学取消申请方可退还入学金以外的费用，入学金不退。', '除服飾研究科、進学科、専攻科等1年制课程外，2年制以上授「专门士」（服饰・家政），ファッション高度専門士科与ファッション流通高度専門士科授「高度专门士」（官网明记）。', '2027年度留学生出愿资格：法务大臣告示日语教育机构出席率80%以上（短期滞在、特定活动期间不计入）。', 'https://www.bunka-fc.ac.jp/prospectivestudent/international-2/', '["1923年文化裁缝女学校创立，1936年改称文化服装学院，1976年获专修学校认可","4课程、26个学科与课程，入学时可选择11科","2007年设4年制ファッション高度専門士科","2026年10月时点留学生930名（中国552、韩国239、台湾53、香港14）","学校兼营文化学园大学、文化学园大学短期大学部"]'::jsonb, '[{"name":"服装科（2年）／服饰研究科（1年）","description":"服饰专门课程；服装科学费模式为入学金260,000＋年授课720,000＋教育充实费360,000。","duration":"2年／1年","totalCost":"入学时990,700／全年1,350,700日元"},{"name":"ファッション高度専門士科（4年）","description":"时尚工科专门课程4年制，授予高度专门士。","duration":"4年","totalCost":"入学时1,070,700／全年1,470,700日元"},{"name":"ファッション工科基礎科（3年）","description":"时尚工科专门课程3年制。","duration":"3年","totalCost":"入学时1,030,700／全年1,390,700日元"},{"name":"ファッション流通高度専門士科（4年）／流通科（2年）／専攻科（1年）","description":"时尚流通专门课程；高度专门士科第3年次教育充实费为660,000日元。","duration":"4年／2年／1年","totalCost":"4年制1,070,700／2年制990,700日元"},{"name":"テキスタイル科（3年）、ジュエリー科・バッグ科（2年）","description":"时尚工艺专门课程，授专门士称号。","duration":"2年／3年","totalCost":"3年制1,030,700／2年制990,700日元"},{"name":"Ⅱ部：服装科（3年）・流通科（2年）","description":"夜间部课程，本批未取得Ⅱ部学费表，待校方要项确认。","duration":"3年／2年","totalCost":"待校方要项确认"}]'::jsonb, '{"enrollmentFee":"入学金260,000日元（2年制各科）／300,000日元（3年制、4年制各科）","admissionFee":"受験料33,000日元（信用卡或二维码支付）","annualTuition":"年授课费720,000日元（前期360,000＋后期360,000）；4年制各科年800,000日元（前期400,000＋后期400,000）","facilitiesFee":"教育充实费（实验实习・教材・设施维持）年360,000日元；时尚流通高度专门士科第3年次为660,000日元","practiceMaterialsFee":"包含在教育充实费内，官网未单列","totalFirstYear":"入学时缴纳990,700～1,070,700日元；全年合计1,350,700～1,470,700日元"}'::jsonb, '["服装设计方向","打版/技术方向","时尚流通与品牌企划"]'::jsonb, '["文化服装学院奖学金：减免当年前期授课费，若干名（上学年49人申请、10人采用）","JASSO 文部科学省外国人留学生学习奖励费：月额48,000日元、1年、限2年级以上（上学年采用10名）","共立国际交流奖学财团月额6万或10万日元、国际协和奖学会月额12万日元、堀田育英财团月额8万日元、Pal井上财团月额3万日元","文化学园各校毕业生：受験料与入学金减半；文化外国语专门学校毕业生：受験料减半、入学金扣除已缴部分"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
COMMIT;
